import 'package:flutter/material.dart';import '../../core/api.dart';import 'director_console_page.dart';
class DirectorSetupPage extends StatefulWidget{const DirectorSetupPage({super.key});@override State<DirectorSetupPage> createState()=>_S();}class _S extends State<DirectorSetupPage>{final title=TextEditingController(text:'My YohPal Live');bool busy=false;Future<void> go()async{setState(()=>busy=true);try{final api=MeshApi();final p=await api.createProduction(title.text);final d=await api.pairingToken(p['id'],role:'DIRECTOR',label:'Director');final c1=await api.pairingToken(p['id'],role:'CAMERA',label:'Camera 1');final c2=await api.pairingToken(p['id'],role:'CAMERA',label:'Camera 2');if(!mounted)return;Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>DirectorConsolePage(productionId:p['id'],token:d['token'],participantId:d['participantId'],cameraPairingUrls:[c1['pairingUrl'],c2['pairingUrl']])));}finally{if(mounted)setState(()=>busy=false);}}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Create Live Production')),body:Padding(padding:const EdgeInsets.all(20),child:Column(children:[TextField(controller:title,decoration:const InputDecoration(labelText:'Production title')),const SizedBox(height:20),FilledButton(onPressed:busy?null:go,child:Text(busy?'Creating…':'Create production'))])));}
